042d4ac852508727.css:
:root {
  --kana-max-width-card: 460px;
  --kana-font-size-glyph: 88px;
  --kana-font-size-romaji: 34px;
  --kana-font-size-mnemonic: 17px;

  --kana-color-page: #0b0716;
  --kana-color-card: #171226;
  --kana-color-text: #f3f1fb;
  --kana-color-accent: #b8aef6;
  --kana-color-muted: #9ca3af;
  --kana-color-divider: #2c2a46;

  --kana-color-nightMode-page: #0b0716;
  --kana-color-nightMode-card: #171226;
  --kana-color-nightMode-text: #f3f1fb;
  --kana-color-nightMode-accent: #b8aef6;
  --kana-color-nightMode-muted: #9ca3af;
  --kana-color-nightMode-divider: #2c2a46;
}

* { box-sizing: border-box; }

body {
  margin: 0 !important;
  line-height: 1.4;
  overflow-wrap: break-word;
  overscroll-behavior: none;
  background: var(--kana-color-page);
}

.nightMode body,
body.nightMode { background: var(--kana-color-nightMode-page); }

.card {
  padding: 12px;
  background: var(--kana-color-page);
}

.nightMode .card { background: var(--kana-color-nightMode-page); }

body,
body.card,
body.nightMode,
.card {
  background: var(--kana-color-page);
  color: var(--kana-color-text);
}

.jpFont {
  font-family: "Yu Mincho", "YuMincho", "Hiragino Mincho ProN", "Noto Serif JP",
    "Noto Sans JP", "Segoe UI", serif;
}

.kanaCard {
  margin: 0 auto;
  max-width: var(--kana-max-width-card);
  width: 100%;
  background: var(--kana-color-card);
  color: var(--kana-color-text);
  border-radius: 12px;
  border-top: 4px solid var(--kana-color-accent);
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.42);
  padding: 24px 20px 28px;
  text-align: center;
  font-family: "Segoe UI", "Noto Sans JP", Arial, sans-serif;
}

.nightMode .kanaCard {
  background: var(--kana-color-nightMode-card);
  color: var(--kana-color-nightMode-text);
  border-top-color: var(--kana-color-nightMode-accent);
}

.kanaScript {
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--kana-color-accent);
  margin-bottom: 6px;
}

.nightMode .kanaScript { color: var(--kana-color-nightMode-accent); }

.kanaGlyph {
  font-size: var(--kana-font-size-glyph);
  font-weight: 700;
  line-height: 1.1;
}

.kanaHint {
  margin-top: 16px;
  font-size: 13px;
  font-style: italic;
  color: var(--kana-color-muted);
}

.nightMode .kanaHint { color: var(--kana-color-nightMode-muted); }

.kanaDivider {
  border: 0;
  border-top: 1px solid var(--kana-color-divider);
  margin: 18px 0;
}

.nightMode .kanaDivider { border-top-color: var(--kana-color-nightMode-divider); }

.kanaRomaji {
  font-size: var(--kana-font-size-romaji);
  font-weight: 700;
  color: var(--kana-color-accent);
}

.nightMode .kanaRomaji { color: var(--kana-color-nightMode-accent); }

.kanaAudio { margin-top: 8px; }

.kanaStrokeAnim img,
.kanaPicture img,
.kanaStrokes img {
  max-width: 100%;
  height: auto;
  border-radius: 8px;
}

.kanaStrokeAnim { margin-top: 12px; }
.kanaPicture { margin-top: 16px; }
.kanaStrokes { margin-top: 12px; }

.kanaMnemonic {
  margin-top: 16px;
  font-size: var(--kana-font-size-mnemonic);
  text-align: left;
  line-height: 1.5;
}

.kanaMnemonic code {
  font-weight: 600;
  color: var(--kana-color-accent);
}

.nightMode .kanaMnemonic code { color: var(--kana-color-nightMode-accent); }

.replay-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: auto;
  height: auto;
  padding: 0;
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  border-radius: 0;
  box-shadow: none !important;
  line-height: 0;
  -webkit-appearance: none;
  appearance: none;
}

.replay-button svg { width: 24px; height: 24px; }
.replay-button svg path { fill: var(--kana-color-accent) !important; }
.nightMode .replay-button svg path { fill: var(--kana-color-nightMode-accent) !important; }
.replay-button svg circle { fill: transparent !important; stroke: none !important; }

043d63996262ca16.css:
:root {
  color-scheme: dark;
  --max-width-card: 620px;
  --font-size-card: 16px;
  --font-size-targetWord: 42px;
  --color-page-background: #0a1220;
  --color-card-background: #0f1b2d;
  --color-nightMode-card-background: #0f1b2d;
  --color-text-primary: #e8f0fe;
  --color-nightMode-text-primary: #e8f0fe;
  --color-audio-button: #93c5fd;
  --color-sentence-translation: #93c5fd;
  --color-nightMode-sentence-translation: #93c5fd;
  --color-nightMode-hint: #93c5fd;
  --color-divider: #24405f;
}
* { box-sizing: border-box; }
html,
body,
.card,
body.nightMode {
  margin: 0;
  background: var(--color-page-background);
  color: var(--color-text-primary);
  font-family: Georgia, Cambria, "Times New Roman", Times, serif;
}
.card { padding: 16px; min-height: 100vh; }
#qa { width: 100%; min-width: 0; margin: 0 auto; }
.customCard {
  width: 100%;
  max-width: var(--max-width-card);
  min-width: 0;
  margin: 0 auto;
  padding: 26px 20px 20px;
  border-radius: 16px;
  border-top: 4px solid #3b82f6;
  background: var(--color-card-background);
  color: var(--color-text-primary);
  box-shadow: 0 8px 30px rgba(0, 0, 0, 0.45);
  font-size: var(--font-size-card);
  text-align: left;
  overflow-wrap: anywhere;
}
.horizontalPadding { width: 100%; min-width: 0; }
.targetWordContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  text-align: center;
}
.wordBlock { display: flex; flex-direction: column; gap: 4px; min-width: 0; max-width: 100%; }
.targetWord {
  font-size: var(--font-size-targetWord);
  font-weight: 800;
  letter-spacing: -0.5px;
  line-height: 1.1;
  color: #bfdbfe;
  overflow-wrap: anywhere;
}
.ipa { font-size: 15px; font-weight: 400; color: #7f9bc4; }
.dividerLine { border-top: 1px solid var(--color-divider); margin: 18px 0; }
.header {
  color: #93c5fd;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  margin: 0 0 8px;
}
.indent { padding: 0; }
.definitionsList { list-style: none; padding: 0; margin: 0; font-size: 16px; line-height: 1.55; }
.examplePanel {
  display: block;
  width: 100%;
  min-width: 0;
  padding: 12px 14px;
  border-left: 3px solid #3b82f6;
  border-radius: 8px;
  background: #12213a;
}
.exampleSentenceLine { display: block; min-width: 0; }
.exampleSentenceText { font-size: 17px; line-height: 1.5; min-width: 0; overflow-wrap: anywhere; }
.exampleSentenceText mark { background: #1e3a5f; color: #dbeafe; border-radius: 4px; padding: 0 3px; }
.sentenceTranslation {
  width: 100%;
  min-width: 0;
  margin-top: 10px;
  padding: 0;
  font-size: 15px;
  line-height: 1.5;
  font-weight: 400;
  font-style: italic;
  color: var(--color-sentence-translation);
  white-space: normal;
  overflow-wrap: anywhere;
}
.wordAudioButtonBack,
.sentenceAudioButton { display: inline-flex; vertical-align: middle; }
.sentenceAudioButton { margin-left: 6px; }
.replay-button,
.soundLink {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  margin: 0;
  padding: 0;
  border-radius: 50%;
  background: #12213a;
  border: 1px solid #24405f;
  color: var(--color-audio-button);
  text-decoration: none;
  vertical-align: middle;
}
.replay-button svg { width: 18px; height: 18px; }
.replay-button svg path { fill: var(--color-audio-button); }
.replay-button svg circle { fill: none; stroke: none; }
.replay-button:focus-visible,
.soundLink:focus-visible { outline: 2px solid #93c5fd; outline-offset: 2px; }
.image { margin: 18px 0; width: 100%; }
.image img { display: block; object-fit: contain; max-width: 100% !important; max-height: 210px !important; height: auto !important; margin: 0 auto; }

0c4e1072deeff50d.css:
:root {
  --max-width-card: 400px;
  --font-size-card: 18px;
  --font-size-targetWord: 26px;
  --font-size-header: 14px;
  --font-size-irregular-form: 15px;

  --color-page-background: #0a1628;
  --color-text-primary: #e8f0fe;
  --color-nightMode-text-primary: #e8f0fe;
  --color-card-background: #0a1628;
  --color-nightMode-card-background: #0a1628;
  --color-box-shadow: rgba(0, 0, 0, 0.45);
  --color-audio-button: #93c5fd;
  --color-list-bullets: #93c5fd;
  --color-irregular-form-background: #1e3a5f;
  --color-nightMode-irregular-form-background: #1e3a5f;
  --color-irregular-form-border: #2563eb;
  --color-nightMode-irregular-form-border: #2563eb;
  --color-nightMode-irregular-form-text: rgba(219, 234, 254, 0.85);
  --color-hint: #93c5fd;
  --color-nightMode-hint: #93c5fd;
  --color-sentence-translation: #93c5fd;
  --color-nightMode-sentence-translation: #93c5fd;
  --color-header: rgba(147, 197, 253, 0.7);
  --color-nightMode-header: rgba(147, 197, 253, 0.7);
  --color-divider: #1e3a5f;
  --color-nightMode-divider: #1e3a5f;
}

/* Chrome Base Styles */
p {
  display: block;
  margin-block-start: 1em;
  margin-block-end: 1em;
  margin-inline-start: 0px;
  margin-inline-end: 0px;
}

div { display: block; }

body {
  display: block;
  line-height: 1.187;
}

html { display: block; }

span, applet, object, iframe,
h1, h2, h3, h4, h5, h6,
blockquote, pre, a, abbr, acronym, address, big, cite, code,
del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong,
sub, sup, tt, var, b, u, i, center,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td,
article, aside, canvas, details, embed,
figure, figcaption, footer, header, hgroup,
menu, nav, output, ruby, section, summary,
time, mark, audio, video {
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 100%;
  font: inherit;
  vertical-align: baseline;
}

article, aside, details, figcaption, figure,
footer, header, hgroup, menu, nav, section {
  display: block;
}

ol, ul { list-style: none; }

blockquote, q { quotes: none; }

blockquote:before, blockquote:after,
q:before, q:after {
  content: "";
  content: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

* { box-sizing: border-box; }

/* ========== NIGHT MODE SCROLLBAR ========== */

body.nightMode::-webkit-scrollbar {
  background: #0a1628;
}
body.nightMode::-webkit-scrollbar:horizontal { height: 12px; }
body.nightMode::-webkit-scrollbar:vertical { width: 12px; }
body.nightMode::-webkit-scrollbar-thumb {
  background: #2563eb;
  border-radius: 8px;
}
body.nightMode::-webkit-scrollbar-thumb:horizontal { min-width: 50px; }
body.nightMode::-webkit-scrollbar-thumb:vertical { min-height: 50px; }

/* ========== BASE ========== */

body {
  overscroll-behavior: none;
  margin: 0 !important;
  overflow-wrap: break-word;
}

#_flag {
  position: fixed;
  right: 10px;
  top: 0;
  font-size: 30px;
  display: none;
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: black;
}

#_mark {
  position: fixed;
  left: 10px;
  top: 0;
  font-size: 30px;
  color: yellow;
  display: none;
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: black;
}

#typeans {
  width: 100%;
  box-sizing: border-box;
}

.typeGood { background: #0f0; }
.typeBad { background: #f00; }
.typeMissed { background: #ccc; }
.nightMode .latex { filter: invert(100%); }
.drawing { zoom: 50%; }
.nightMode img.drawing { filter: invert(1) hue-rotate(180deg); }

/* ========== CARD STYLES ========== */

.card {
  padding: 16px;
}

body,
body.card,
body.nightMode,
.card {
  background: var(--color-page-background);
  color: var(--color-text-primary);
}

.customCard {
  margin: 0 auto;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;

  background-color: var(--color-card-background);
  box-shadow:
    0 4px 24px var(--color-box-shadow),
    0 1px 4px rgba(37, 99, 235, 0.08);
  border-radius: 16px;
  border-top: 4px solid #2563eb;
  min-height: 200px;
  max-width: var(--max-width-card);

  font-weight: 500;
  font-size: var(--font-size-card);
  font-family: "Segoe UI", "Noto Sans", Arial, sans-serif;
  color: var(--color-text-primary);
}

.nightMode .customCard {
  color: var(--color-nightMode-text-primary);
  background-color: var(--color-nightMode-card-background);
}

.cardBack {
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  padding-top: 24px;
  padding-bottom: 8px;
}

.sortIndex {
  display: none;
}

.targetWordContainer {
  margin-top: 8px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.targetWord {
  font-size: var(--font-size-targetWord);
  font-weight: 700;
  color: #93c5fd;
  letter-spacing: -0.5px;
}

.wordBlock {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ipa {
  font-size: 14px;
  color: var(--color-divader);
  margin-left: 2px;
  font-weight: 400;
  letter-spacing: 0.03em;
  opacity: 0.7;
}

.nightMode .targetWord {
  color: #93c5fd;
}

.definitionsList {
  list-style: none;
  margin: 0;
  padding: 0;
  padding-left: 16px;
}

.definitionsList li {
  margin-bottom: 6px;
  line-height: 1.5;
}

.definitionsList li::before {
  content: "\2022";
  color: var(--color-list-bullets);
  display: inline-block;
  width: 8px;
  margin-right: 5px;
  margin-left: -16px;
  font-size: 22px;
}

.wordAudioButtonFront {
  position: absolute;
  top: 21px;
  right: 22px;
}

.wordAudioButtonBack {
  margin-left: 8px;
}

.exampleSentenceLine {
  display: flex;
  align-items: center;
  gap: 8px;
}

.exampleSentenceText {
  flex: 1 1 auto;
  min-width: 0;
}

.sentenceAudioButton {
  flex: 0 0 auto;
  margin-left: 8px;
}

.replay-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: auto;
  height: auto;
  padding: 0;
  background: transparent !important;
  background-color: transparent !important;
  border: 0 !important;
  border-radius: 0;
  box-shadow: none !important;
  line-height: 0;
  -webkit-appearance: none;
  appearance: none;
}

.replay-button svg {
  width: 20px;
  height: 20px;
}

.replay-button svg path {
  fill: var(--color-audio-button) !important;
}

.replay-button svg circle {
  fill: transparent !important;
  stroke: none !important;
}

.irregularFormsContainer {
  display: flex;
  flex-wrap: wrap;
  margin-top: 12px;
}

.irregularForm {
  background-color: var(--color-irregular-form-background);
  border: 1px solid var(--color-irregular-form-border);
  border-radius: 40px;
  font-size: var(--font-size-irregular-form);
  color: #1d4ed8;
  font-weight: 600;
  padding: 3px 12px 5px;
  margin-right: 10px;
  margin-bottom: 8px;
}

.nightMode .irregularForm {
  color: var(--color-nightMode-irregular-form-text);
  background-color: var(--color-nightMode-irregular-form-background);
  border-color: var(--color-nightMode-irregular-form-border);
}

.image {
  border-top: 1px solid var(--color-divider);
  border-bottom: 1px solid var(--color-divider);
  margin-top: 16px;
  width: 100%;
  height: 210px;
}

.image img {
  object-fit: contain;
  width: 100% !important;
  height: 100% !important;
  max-width: 100% !important;
  max-height: 100% !important;
}

.hint { color: var(--color-hint); }
.nightMode .hint { color: var(--color-nightMode-hint); }

.sentenceTranslation {
  color: var(--color-sentence-translation);
  font-weight: 400;
  font-style: italic;
  padding-right: 15px;
  padding-top: 8px;
}

.nightMode .sentenceTranslation {
  color: var(--color-nightMode-sentence-translation);
}

.reportIconContainer {
  width: 100%;
  display: flex;
  justify-content: flex-end;
  align-items: center;
}

.header {
  color: var(--color-header);
  font-size: var(--font-size-header);
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin-top: 8px;
  margin-bottom: 8px;
}

.nightMode .header {
  color: var(--color-nightMode-header);
}

.dividerLine {
  width: 100%;
  border-bottom: 1px solid var(--color-divider);
  margin-top: 8px;
  margin-bottom: 8px;
}

.nightMode .dividerLine {
  border-color: var(--color-nightMode-divider);
}

.horizontalPadding {
  width: 100%;
  padding-left: 16px;
  padding-right: 16px;
}

.indent {
  padding-left: 12px;
}

.centerVertically {
  display: flex;
  align-items: center;
}

