  height: 2px;
  background: linear-gradient(to right, transparent, #4CAF50, transparent);
  margin: 25px 10%;
}

.card, .card * {
  font-family: "Noto Sans KR", "Apple SD Gothic Neo", "Malgun Gothic", sans-serif;
  word-break: keep-all;
  overflow-wrap: anywhere;
