97443c42d9980f89.css:
:root {
  --max-width-card: 680px;
  --font-size-card: 18px;
  --font-size-targetWord: 38px;
  --font-size-header: 12px;
  --font-size-irregular-form: 15px;

  --color-page-background: #121212;
  --color-text-primary: #EAEAEA;
  --color-nightMode-text-primary: #EAEAEA;
  --color-card-background: #1E1E1E;
  --color-nightMode-card-background: #1E1E1E;
  --color-panel-background: transparent;
  --color-box-shadow: rgba(0, 0, 0, 0.5);
  --color-audio-button: #A0A0A0;
  --color-list-bullets: #A0A0A0;
  --color-irregular-form-background: #eff6ff;
  --color-nightMode-irregular-form-background: #1e3a5f;
  --color-irregular-form-border: #bfdbfe;
  --color-nightMode-irregular-form-border: #2563eb;
  --color-nightMode-irregular-form-text: rgba(219, 234, 254, 0.85);
  --color-hint: #A0A0A0;
  --color-nightMode-hint: #A0A0A0;
  --color-sentence-translation: #A0A0A0;
  --color-nightMode-sentence-translation: #A0A0A0;
  --color-header: #A0A0A0;
  --color-nightMode-header: #A0A0A0;
  --color-text-muted: #A0A0A0;
  --color-divider: #333333;
  --color-nightMode-divider: #333333;
}

/* Chrome Base Styles */
p {
  display: block;
  margin-block-start: 1em;
  margin-block-end: 1em;
  margin-inline-start: 0px;
  margin-inline-end: 0px;
}

div { display: block; }

body {
  display: block;
  line-height: 1.187;
}

html { display: block; }

span, applet, object, iframe,
h1, h2, h3, h4, h5, h6,
blockquote, pre, a, abbr, acronym, address, big, cite, code,
del, dfn, em, img, ins, kbd, q, s, samp, small, strike, strong,
sub, sup, tt, var, b, u, i, center,
dl, dt, dd, ol, ul, li,
fieldset, form, label, legend,
table, caption, tbody, tfoot, thead, tr, th, td,
article, aside, canvas, details, embed,
figure, figcaption, footer, header, hgroup,
menu, nav, output, ruby, section, summary,
time, mark, audio, video {
  margin: 0;
  padding: 0;
  border: 0;
  font-size: 100%;
  font: inherit;
  vertical-align: baseline;
}

article, aside, details, figcaption, figure,
footer, header, hgroup, menu, nav, section {
  display: block;
}

ol, ul { list-style: none; }

blockquote, q { quotes: none; }

blockquote:before, blockquote:after,
q:before, q:after {
  content: "";
  content: none;
}

table {
  border-collapse: collapse;
  border-spacing: 0;
}

* { box-sizing: border-box; }

/* ========== NIGHT MODE SCROLLBAR ========== */

body.nightMode::-webkit-scrollbar {
  background: var(--color-page-background);
}
body.nightMode::-webkit-scrollbar:horizontal { height: 12px; }
body.nightMode::-webkit-scrollbar:vertical { width: 12px; }
body.nightMode::-webkit-scrollbar-thumb {
  background: var(--color-text-muted);
  border-radius: 8px;
}
body.nightMode::-webkit-scrollbar-thumb:horizontal { min-width: 50px; }
body.nightMode::-webkit-scrollbar-thumb:vertical { min-height: 50px; }

/* ========== BASE ========== */

body {
  overscroll-behavior: none;
  margin: 0 !important;
  overflow-wrap: break-word;
}

#_flag {
  position: fixed;
  right: 10px;
  top: 0;
  font-size: 30px;
  display: none;
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: black;
}

#_mark {
  position: fixed;
  left: 10px;
  top: 0;
  font-size: 30px;
  color: yellow;
  display: none;
  -webkit-text-stroke-width: 1px;
  -webkit-text-stroke-color: black;
}

#typeans {
  width: 100%;
  box-sizing: border-box;
}

.typeGood { background: #0f0; }
.typeBad { background: #f00; }
.typeMissed { background: #ccc; }
.nightMode .latex { filter: invert(100%); }
.drawing { zoom: 50%; }
.nightMode img.drawing { filter: invert(1) hue-rotate(180deg); }

/* ========== CARD STYLES ========== */

.card {
  padding: 16px;
}

.customCard {
  margin: 0 auto;
  position: relative;
  display: flex;
  justify-content: center;
  align-items: center;

  background-color: var(--color-card-background);
  box-shadow:
    0 4px 24px var(--color-box-shadow),
    0 1px 4px rgba(37, 99, 235, 0.08);
  border-radius: 8px;
  border: 1px solid var(--color-divider);
  min-height: 200px;
  max-width: var(--max-width-card);

  font-weight: 500;
  font-size: var(--font-size-card);
  font-family: "Segoe UI", "Noto Sans", Arial, sans-serif;
  color: var(--color-text-primary);
}

.nightMode .customCard {
  color: var(--color-nightMode-text-primary);
  background-color: var(--color-nightMode-card-background);
}

.cardBack {
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  padding-top: 24px;
  padding-bottom: 8px;
}

.targetWordContainer {
  margin-top: 8px;
  margin-bottom: 24px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
}

.targetWord {
  font-size: var(--font-size-targetWord);
  font-weight: 700;
  color: var(--color-text-primary);
  letter-spacing: -0.5px;
}

.wordBlock {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.ipa {
  font-size: 14px;
  color: var(--color-divader);
  margin-left: 2px;
  font-weight: 400;
  letter-spacing: 0.03em;
  opacity: 0.7;
}

.nightMode .targetWord {
  color: var(--color-text-primary);
}

.definitionsList {
  list-style: none;
  margin: 0;
  padding: 0;
  padding-left: 16px;
}

.definitionsList li {
  margin-bottom: 6px;
  line-height: 1.5;
}

.definitionsList li::before {
  content: "\2022";
  color: var(--color-list-bullets);
